public void validateAndFreeze(long releaseId, String model, TopologyRequest topology) {
    List<String> deviceIds = topology.deviceIds();
    if (new HashSet<>(deviceIds).size() != deviceIds.size()) throw badRequest("TOPOLOGY_DUPLICATE_DEVICE", ...);
    Map<String, Device> devices = deviceRepository.findByIds(deviceIds) → map;
    for (String id : deviceIds) {
        Device d = devices.get(id);
        if (d == null) throw badRequest("TOPOLOGY_DEVICE_UNKNOWN", ...);
        if (!d.model().equals(model)) throw badRequest("TOPOLOGY_MODEL_MISMATCH", ...);
    }
    Set<String> seen = new HashSet<>();
    for (TopologyEdgeRequest e : topology.edges()) {
        if (e.a().equals(e.b())) throw badRequest("TOPOLOGY_SELF_LOOP", ...);
        if (!deviceSet.contains(e.a()) || !deviceSet.contains(e.b())) throw badRequest("TOPOLOGY_EDGE_UNKNOWN_DEVICE", ...);
        String a = min, b = max;
        if (!seen.add(a + "|" + b)) throw badRequest("TOPOLOGY_DUPLICATE_EDGE", ...);
